using Microsoft.AspNetCore.Mvc;using GameVault.Services;using GameVault.Models;using GameVault.ViewModels;
namespace GameVault.Controllers;
public class AccountController(GameVaultStore store):Controller { public IActionResult Register()=>View(); [HttpPost,ValidateAntiForgeryToken] public IActionResult Register(RegisterViewModel m){if(!ModelState.IsValid)return View(m);var u=new AppUser{Name=m.Name.Trim(),Email=m.Email.Trim().ToLowerInvariant(),PasswordHash=GameVaultStore.Hash(m.Password)};if(!store.Register(u)){ModelState.AddModelError("Email","An account with this email already exists.");return View(m);}HttpContext.Session.SetString("Email",u.Email);HttpContext.Session.SetString("Name",u.Name);return RedirectToAction("Index","Home");} public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View();} [HttpPost,ValidateAntiForgeryToken] public IActionResult Login(LoginViewModel m,string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;if(!ModelState.IsValid)return View(m);var u=store.User(m.Email.Trim());if(u==null||!GameVaultStore.Verify(m.Password,u.PasswordHash)){ModelState.AddModelError("","Email or password is incorrect.");return View(m);}HttpContext.Session.SetString("Email",u.Email);HttpContext.Session.SetString("Name",u.Name);if(!string.IsNullOrEmpty(returnUrl)&&Url.IsLocalUrl(returnUrl))return LocalRedirect(returnUrl);return RedirectToAction("Index","Home");} [HttpPost,ValidateAntiForgeryToken] public IActionResult Logout(){HttpContext.Session.Clear();return RedirectToAction("Index","Home");} }
